<div class="d-flex justify-content-between align-items-center mb-3"><div><h1 class="h3 mb-1">Expense #<?=e($expense['id'])?></h1><p class="text-muted mb-0">Expense details and audit-ready information.</p></div><div class="d-flex gap-2"><a href="<?=url('expenses')?>" class="action-button action-button--neutral btn btn-outline-secondary"><i data-feather="arrow-left" aria-hidden="true"></i>Back</a><?php if(can('expenses.edit') && (int)$expense['user_id']===(int)auth_user()['id']):?><a href="<?=url('expenses/'.$expense['id'].'/edit')?>" class="action-button action-button--primary btn btn-primary"><i data-feather="edit-3" aria-hidden="true"></i>Edit</a><?php endif;?></div></div><div class="card"><div class="card-body"><div class="row g-4"><div class="col-md-4"><div class="text-muted">Amount</div><div class="h2"><?=money($expense['amount'])?></div></div><div class="col-md-4"><div class="text-muted">Date</div><div class="h5"><?=e(display_date($expense['expense_date']))?></div></div><div class="col-md-4"><div class="text-muted">Status</div><span class="status-badge status-badge--<?=in_array($expense['status'], ['active', 'posted'], true) ? 'success' : 'neutral'?>"><i data-feather="<?=in_array($expense['status'], ['active', 'posted'], true) ? 'check-circle' : 'pause-circle'?>" aria-hidden="true"></i><?=e($expense['status'])?></span></div><div class="col-md-6"><div class="text-muted">Category</div><div class="h5"><?=e($expense['category_name'])?></div></div><div class="col-md-6"><div class="text-muted">Account</div><div class="h5"><?=e($expense['account_name'])?></div></div><div class="col-12"><div class="text-muted">Description</div><div><?=e($expense['description'])?></div></div><div class="col-12"><div class="text-muted">Notes</div><div><?=nl2br(e($expense['notes']))?></div></div><div class="col-12"><div class="text-muted">Receipt</div><?php if(!empty($expense['receipt_path'])):?><div class="current-file mt-2"><i data-feather="paperclip" aria-hidden="true"></i><span><?=e(basename($expense['receipt_path']))?></span><a href="<?=e(url('expenses/'.$expense['id'].'/receipt'))?>" target="_blank" rel="noopener">View file</a></div><?php else:?><div class="text-muted">No receipt attached.</div><?php endif;?></div></div><?php if(can('expenses.delete') && (int)$expense['user_id']===(int)auth_user()['id']):?><hr><form method="post" action="<?=url('expenses/'.$expense['id'].'/delete')?>" data-confirm-title="Delete Expense" data-confirm-subtitle="This action cannot be undone." data-confirm-message="Deleting this expense permanently removes it and restores the amount to the linked account balance." data-confirm-button="Delete Expense"><?=csrf_field()?><button class="action-button action-button--danger btn btn-outline-danger"><i data-feather="trash-2" aria-hidden="true"></i>Delete Expense</button></form><?php endif;?></div></div>
